contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance if sending Ether
        require(address(this).balance >= amount);

        // read balance of this contract in c before the operation
        uint before = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        bool reverted;
        // call Deposit on c sending `amount` wei
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cBalAfter = address(c).balance;

        // If the call did not revert then the recorded balance must have increased by amount
        // and the contract's Ether balance must also have increased by amount.
        // If it reverted then neither observable should have increased (they remain equal to before).
        assert(
            reverted
            ? (afterBal == before && cBalAfter == cBalBefore)
            : (afterBal == before + amount && cBalAfter == cBalBefore + amount)
        );
    }

    receive() external payable {}
}

